dashboard.definition:
{
  "title": "Linux System & Security",
  "description": "Linux operational signals \u2014 SAP application activity, firewall drops, kernel events, and instance distribution",
  "inputs": {
    "input_global_trp": {
      "options": {
        "defaultValue": "-30d@d,now",
        "token": "global_time"
      },
      "title": "Global Time Range",
      "type": "input.timerange"
    },
    "input_nav_dropdown": {
      "type": "input.dropdown",
      "title": "Navigate to Dashboard",
      "options": {
        "items": [
          {
            "label": "Overview",
            "value": "logserv_overview"
          },
          {
            "label": "Network Perimeter",
            "value": "logserv_network_perimeter"
          },
          {
            "label": "DNS Analytics",
            "value": "logserv_dns_analytics"
          },
          {
            "label": "HANA Audit",
            "value": "logserv_hana_audit"
          },
          {
            "label": "HANA Trace",
            "value": "logserv_hana_trace"
          },
          {
            "label": "Web Dispatcher",
            "value": "logserv_web_dispatcher"
          },
          {
            "label": "Web and API Performance",
            "value": "logserv_web_api_performance"
          },
          {
            "label": "Host Details",
            "value": "logserv_host_details"
          },
          {
            "label": "ABAP Security",
            "value": "logserv_abap_security"
          },
          {
            "label": "ABAP Operations",
            "value": "logserv_abap_operations"
          },
          {
            "label": "SAP Services",
            "value": "logserv_sap_services"
          },
          {
            "label": "Cloud Connector",
            "value": "logserv_cloud_connector"
          },
          {
            "label": "Windows",
            "value": "logserv_windows"
          },
          {
            "label": "Proxy",
            "value": "logserv_proxy"
          },
          {
            "label": "Environment Health",
            "value": "logserv_environment_health"
          },
          {
            "label": "Cross-Stack Authentication",
            "value": "logserv_cross_stack_authentication"
          },
          {
            "label": "Change & Configuration Activity",
            "value": "logserv_change_config"
          },
          {
            "label": "SAP Router",
            "value": "logserv_sap_router"
          },
          {
            "label": "Work Process Performance",
            "value": "logserv_work_process_performance"
          }
        ],
        "token": "nav_target"
      }
    }
  },
  "defaults": {
    "dataSources": {
      "ds.search": {
        "options": {
          "queryParameters": {
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$"
          }
        }
      }
    }
  },
  "visualizations": {
    "viz_kpi_total": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_kpi_total"
      },
      "title": "Total Events",
      "options": {
        "majorValue": "> primary | seriesByName('total') | lastPoint()",
        "sparklineValue": "> primary | seriesByName('daily')",
        "backgroundColor": "transparent",
        "labelColor": "#7b8ea8",
        "labelFontSize": 13,
        "majorColor": "#ffffff",
        "majorFontSize": 36,
        "sparklineDisplay": "below",
        "trendDisplay": "off"
      }
    },
    "viz_kpi_fw_drops": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_kpi_fw_drops"
      },
      "title": "Firewall Drops",
      "options": {
        "majorValue": "> primary | seriesByName('total') | lastPoint()",
        "sparklineValue": "> primary | seriesByName('daily')",
        "backgroundColor": "transparent",
        "labelColor": "#7b8ea8",
        "labelFontSize": 13,
        "majorColor": "#dc4e41",
        "majorFontSize": 36,
        "sparklineDisplay": "below",
        "trendDisplay": "off"
      }
    },
    "viz_kpi_hosts": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_kpi_hosts"
      },
      "title": "Active Hosts",
      "options": {
        "majorValue": "> primary | seriesByName('total') | lastPoint()",
        "sparklineValue": "> primary | seriesByName('daily')",
        "backgroundColor": "transparent",
        "labelColor": "#7b8ea8",
        "labelFontSize": 13,
        "majorColor": "#ffffff",
        "majorFontSize": 36,
        "sparklineDisplay": "below",
        "trendDisplay": "off"
      }
    },
    "viz_volume_by_type": {
      "type": "splunk.line",
      "dataSources": {
        "primary": "ds_volume_by_type"
      },
      "title": "Event Volume by Sourcetype",
      "showProgressBar": false,
      "showLastUpdated": false,
      "options": {
        "backgroundColor": "transparent",
        "xAxisTitleVisibility": "hide",
        "yAxisTitleVisibility": "hide",
        "dataValuesDisplay": "off"
      }
    },
    "viz_sap_app_activity": {
      "type": "splunk.column",
      "dataSources": {
        "primary": "ds_sap_app_activity"
      },
      "title": "SAP Application Activity",
      "showProgressBar": false,
      "showLastUpdated": false,
      "options": {
        "backgroundColor": "transparent",
        "stackMode": "stacked",
        "xAxisTitleVisibility": "hide",
        "yAxisTitleVisibility": "hide",
        "dataValuesDisplay": "off"
      }
    },
    "viz_sap_instances": {
      "type": "splunk.table",
      "dataSources": {
        "primary": "ds_sap_instances"
      },
      "title": "SAP Instance Distribution",
      "showProgressBar": false,
      "showLastUpdated": false,
      "options": {
        "backgroundColor": "transparent",
        "headerBackgroundColor": "#1e2a3d",
        "rowBackgroundColorEven": "transparent",
        "rowBackgroundColorOdd": "#0d1520",
        "headerVisibility": "fixed"
      }
    },
    "viz_fw_timeline": {
      "type": "splunk.column",
      "dataSources": {
        "primary": "ds_fw_timeline"
      },
      "title": "Firewall Drops Over Time",
      "showProgressBar": false,
      "showLastUpdated": false,
      "options": {
        "backgroundColor": "transparent",
        "xAxisTitleVisibility": "hide",
        "yAxisTitleVisibility": "hide",
        "seriesColors": [
          "#dc4e41"
        ],
        "dataValuesDisplay": "off"
      }
    },
    "viz_fw_top_sources": {
      "type": "splunk.table",
      "dataSources": {
        "primary": "ds_fw_top_sources"
      },
      "title": "Top Blocked Sources",
      "showProgressBar": false,
      "showLastUpdated": false,
      "options": {
        "backgroundColor": "transparent",
        "headerBackgroundColor": "#1e2a3d",
        "rowBackgroundColorEven": "transparent",
        "rowBackgroundColorOdd": "#0d1520",
        "headerVisibility": "fixed"
      }
    },
    "viz_fw_top_ports": {
      "type": "splunk.table",
      "dataSources": {
        "primary": "ds_fw_top_ports"
      },
      "title": "Top Blocked Destination Ports",
      "showProgressBar": false,
      "showLastUpdated": false,
      "options": {
        "backgroundColor": "transparent",
        "headerBackgroundColor": "#1e2a3d",
        "rowBackgroundColorEven": "transparent",
        "rowBackgroundColorOdd": "#0d1520",
        "headerVisibility": "fixed"
      }
    },
    "viz_kernel_events": {
      "type": "splunk.pie",
      "dataSources": {
        "primary": "ds_kernel_events"
      },
      "title": "Kernel Event Types",
      "showProgressBar": false,
      "showLastUpdated": false,
      "options": {
        "showDonutHole": true,
        "backgroundColor": "transparent"
      }
    },
    "viz_rect_r1l": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_rect_r1r": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_rect_r2l": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_rect_r2m": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_rect_r2r": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_rect_r3l": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_rect_r3r": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_nav_go": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_nav_go"
      },
      "options": {
        "majorValue": "> primary | seriesByName('label') | lastPoint()",
        "backgroundColor": "#0877a6",
        "majorColor": "#ffffff",
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorFontSize": 16
      },
      "eventHandlers": [
        {
          "type": "drilldown.customUrl",
          "options": {
            "url": "/app/splunk_app_sap_logserv/$nav_target$?form.global_time.earliest=$global_time.earliest$&form.global_time.latest=$global_time.latest$",
            "newTab": false
          }
        }
      ]
    },
    "viz_kpi_rect_1": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_kpi_rect_2": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_kpi_rect_3": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    },
    "viz_kpi_top_drop_src": {
      "type": "splunk.singlevalue",
      "dataSources": {
        "primary": "ds_kpi_top_drop_src"
      },
      "title": "Top Drop Source",
      "options": {
        "majorValue": "> primary | seriesByName('display') | lastPoint()",
        "backgroundColor": "transparent",
        "labelColor": "#7b8ea8",
        "labelFontSize": 13,
        "majorColor": "#dc4e41",
        "majorFontSize": 28,
        "sparklineDisplay": "off",
        "trendDisplay": "off"
      },
      "eventHandlers": [
        {
          "type": "drilldown.customUrl",
          "options": {
            "url": "/app/search/search?q=%60sap_logserv_idx_macro%60%20sourcetype%3D%22linux_secure%22%20%7C%20rex%20field%3D_raw%20%22SRC%3D%28%3F%3Cfw_src%3E%5B%5E%20%5D%2B%29%22%20%7C%20where%20isnotnull%28fw_src%29%20%7C%20stats%20count%20as%20Drops%2C%20dc%28host%29%20as%20Hosts%2C%20values%28host%29%20as%20%22Hosts%20Affected%22%20by%20fw_src%20%7C%20sort%20-Drops&earliest=$global_time.earliest$&latest=$global_time.latest$",
            "newTab": true
          }
        }
      ]
    },
    "viz_kpi_rect_4": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#141b2d",
        "rx": 3,
        "strokeColor": "#0877a6"
      }
    }
  },
  "dataSources": {
    "ds_kpi_total": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype IN (\"linux_messages_syslog\", \"syslog\", \"linux_secure\") | timechart span=1d count as daily | appendpipe [stats count as _c | where _c=0 | eval _time=now(), daily=0 | fields _time daily] | eventstats sum(daily) as total"
      }
    },
    "ds_kpi_fw_drops": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=\"linux_secure\" | rex field=_raw \"(?<fw_action>IN_DROP|IN_ACCEPT)\" | where fw_action=\"IN_DROP\" | timechart span=1d count as daily | appendpipe [stats count as _c | where _c=0 | eval _time=now(), daily=0 | fields _time daily] | eventstats sum(daily) as total"
      }
    },
    "ds_kpi_hosts": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype IN (\"linux_messages_syslog\", \"syslog\", \"linux_secure\") | eventstats dc(host) as window_dc | timechart span=1d dc(host) as daily, max(window_dc) as total | appendpipe [stats count as _c | where _c=0 | eval _time=now(), daily=0, total=0 | fields _time daily total]"
      }
    },
    "ds_volume_by_type": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype IN (\"linux_messages_syslog\", \"syslog\", \"linux_secure\") | timechart span=1d count by sourcetype"
      }
    },
    "ds_sap_app_activity": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=\"linux_messages_syslog\" sap_app=* | stats count by sap_app sap_sid | sort -count | head 20"
      }
    },
    "ds_sap_instances": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=\"linux_messages_syslog\" sap_sid=* | stats count as Events dc(host) as Hosts by sap_sid sap_inst sap_cid | sort -Events | head 20 | rename sap_sid as SID sap_inst as Instance sap_cid as CID"
      }
    },
    "ds_fw_timeline": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=\"linux_secure\" | timechart span=1d count as \"Firewall Events\""
      }
    },
    "ds_fw_top_sources": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=\"linux_secure\" | rex field=_raw \"SRC=(?<fw_src>[^ ]+)\" | rex field=_raw \"DST=(?<fw_dst>[^ ]+)\" | rex field=_raw \"PROTO=(?<fw_proto>[^ ]+)\" | where isnotnull(fw_src) | stats count as \"Drops\" dc(fw_dst) as \"Targets\" values(fw_proto) as Protocol by fw_src | sort -Drops | head 20 | rename fw_src as \"Source IP\""
      }
    },
    "ds_fw_top_ports": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=\"linux_secure\" | rex field=_raw \"DPT=(?<fw_dpt>[^ ]+)\" | rex field=_raw \"PROTO=(?<fw_proto>[^ ]+)\" | where isnotnull(fw_dpt) | stats count as \"Drops\" dc(host) as Hosts by fw_dpt fw_proto | sort -Drops | head 20 | rename fw_dpt as \"Dest Port\" fw_proto as Protocol"
      }
    },
    "ds_kernel_events": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=\"linux_secure\" | rex field=_raw \"kernel:.*?\\]\\s+(?<kernel_event>[A-Z_]+)\" | where isnotnull(kernel_event) | stats count by kernel_event | sort -count | head 10"
      }
    },
    "ds_nav_go": {
      "type": "ds.search",
      "options": {
        "query": "| makeresults | eval label=\"Go >\"",
        "queryParameters": {
          "earliest": "-1m",
          "latest": "now"
        }
      }
    },
    "ds_kpi_top_drop_src": {
      "type": "ds.search",
      "options": {
        "query": "`sap_logserv_idx_macro` sourcetype=\"linux_secure\" | rex field=_raw \"SRC=(?<fw_src>[^ ]+)\" | where isnotnull(fw_src) AND fw_src!=\"\" | stats count as drops by fw_src | sort -drops | head 1 | eval display = fw_src . \" (\" . tostring(drops, \"commas\") . \")\" | table display, fw_src, drops",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    }
  },
  "layout": {
    "globalInputs": [
      "input_global_trp",
      "input_nav_dropdown"
    ],
    "layoutDefinitions": {
      "layout_1": {
        "options": {
          "display": "fit-to-width",
          "height": 1251,
          "width": 1920,
          "backgroundColor": "#0d1117"
